'use strict';

var fac = require( '@stdlib/plot/unicode/base/lib' );
var opt = {
	'plotAreaHeight': 10,
	'plotAreaWidth': 100,
	'axisData': [ [1, 2, 10], [ 1, 2 ], [ 1, 20], [ 1, 2, 20] ],
	'labelFormate': [ '%0.5f', '%s', '%0.5f', '%0.5f' ],
	'ticsStride': [ 2, 3, 2, 2],
	'backgroundColor': 'Bwhite',
	'foregroundColor': 'Fgreen'
};
var ins = new fac( opt );
var str;
ins.initialize();
var pltar = ins.plotArea;
ins.setBar( [ pltar.y + 8, pltar.x + 3 ], [ pltar.y + 8, pltar.x + 4 ], [ pltar.y + 1, pltar.x + 3 ], [ pltar.y + 1, pltar.x + 4 ], 'block', true );
str = ins.render();
console.log( str );

// console.log('\x1b033[40m');

